// The generated .docx/.pdf are committed build artifacts, regenerated by CI
// whenever a guide's markdown changes (.github/workflows/autofix-ci.yml). That
// only works if identical markdown yields identical bytes — otherwise every
// regeneration run commits a fresh, meaningless binary blob.
//
// Three things made the output non-reproducible, all handled here:
//   1. pandoc stamps wall-clock dcterms:created/modified into docProps/core.xml
//   2. zip records each file's mtime in the archive
//   3. pandoc copies the wordmark's absolute source path into the picture's
//      descr attribute — machine-specific, and not something to publish
//
// Follows the reproducible-builds SOURCE_DATE_EPOCH convention, so the same
// value also feeds LibreOffice's PDF metadata.

import fs from 'node:fs';
import path from 'node:path';

// 1980-01-01T00:00:00Z — the earliest timestamp the zip format can represent,
// and the customary fixed date for reproducible archives.
const DEFAULT_EPOCH = 315532800;

export const SOURCE_DATE_EPOCH = Number(process.env.SOURCE_DATE_EPOCH ?? DEFAULT_EPOCH);

const FIXED_ISO = new Date(SOURCE_DATE_EPOCH * 1000).toISOString().replace(/\.\d{3}Z$/, 'Z');

// Rewrites the two wall-clock timestamps pandoc puts in docProps/core.xml.
// Only the element text is touched; the xsi:type attribute is left alone.
export function normalizeCoreProps(xml) {
  return xml.replace(
    /(<dcterms:(?:created|modified)\b[^>]*>)[^<]*(<\/dcterms:(?:created|modified)>)/g,
    (_match, open, close) => `${open}${FIXED_ISO}${close}`
  );
}

// pandoc records each image's source path as the DrawingML picture description:
//   <pic:cNvPr descr="/Users/somebody/src/medplum/packages/docs/scripts/assets/..." />
// That varies per machine (a runner's path is /home/runner/work/...), which alone
// would make the committed .docx unreproducible — and it would publish a
// contributor's local directory layout in a public repo. Replace it with the bare
// filename, which is what Word itself stores. The human-facing alt text lives in
// <wp:docPr descr="Medplum">, which is untouched.
export function stripImageSourcePaths(xml) {
  return xml.replace(/(<pic:cNvPr\b[^>]*?\bdescr=")([^"]*)(")/g, (match, open, value, close) => {
    if (!value.includes('/')) {
      return match;
    }
    return `${open}${value.slice(value.lastIndexOf('/') + 1)}${close}`;
  });
}

// Stamps every extracted file and directory with the fixed date, so the mtimes
// zip records don't vary between runs.
export function setFixedMtimes(dir) {
  const when = new Date(SOURCE_DATE_EPOCH * 1000);
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      setFixedMtimes(full);
    }
    fs.utimesSync(full, when, when);
  }
  fs.utimesSync(dir, when, when);
}

// Archive member order is part of the bytes, so it can't be left to directory
// traversal order. Returns every file (not directories — a .docx needs no
// directory entries, and real Word output has none) as a sorted list of paths
// relative to `dir`. '[Content_Types].xml' sorts first naturally, as OPC wants.
export function sortedArchiveEntries(dir, prefix = '') {
  const entries = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isDirectory()) {
      entries.push(...sortedArchiveEntries(path.join(dir, entry.name), rel));
    } else {
      entries.push(rel);
    }
  }
  return entries.sort();
}
